function image(ref){return ref?.startsWith('data:image/')?ref:ASSETS[ref]||'';}
function cover(x,tag=''){
 const p=image(x.photos?.[0]);return `<div class="cover">${p?`<img src="${p}" alt="${esc(x.title||x.name)}" loading="lazy">`:`<div class="photo-fallback">${icon(x.kind==='imovel'?'apartment':x.icon||'photo_camera')}</div>`}${tag?`<span class="pill">${esc(tag)}</span>`:''}</div>`;
}
function btn(text,action,value='',kind='filled',ic=''){
 const tag={'filled':'md-filled-button','tonal':'md-filled-tonal-button','text':'md-text-button','outlined':'md-outlined-button'}[kind];return `<${tag} type="button" data-action="${action}"${value!==''?` data-value="${esc(value)}"`:''}>${ic?icon(ic,'icon'):''}${esc(text)}</${tag}>`;
}
function iconBtn(ic,action,value='',label=ic,extra=''){return `<md-icon-button type="button" data-action="${action}" data-value="${esc(value)}" aria-label="${esc(label)}" ${extra}>${icon(ic)}</md-icon-button>`;}
function selectField(id,label,values,selected='',extra=''){
 return `<md-outlined-select id="${id}" label="${esc(label)}" ${extra}>${values.map(v=>{const [value,title]=Array.isArray(v)?v:[v,v];return `<md-select-option value="${esc(value)}" ${String(selected)===String(value)?'selected':''}><div slot="headline">${esc(title)}</div></md-select-option>`;}).join('')}</md-outlined-select>`;
}
// Rodada 42: no celular, campo numérico abre o teclado numérico e campo de busca, a tecla Buscar.
function field(id,label,value='',extra=''){if(/type="number"/.test(extra)&&!/inputmode=/.test(extra))extra+=' inputmode="numeric"';if(/type="search"/.test(extra)&&!/inputmode=/.test(extra))extra+=' inputmode="search"';return `<md-outlined-text-field id="${id}" label="${esc(label)}" value="${esc(value)}" ${extra}></md-outlined-text-field>`;}
function pill(text,kind='',ic=''){return `<span class="pill ${kind}">${ic?icon(ic):''}${esc(text)}</span>`;}
function sectionTitle(title,label='',action='',value=''){return `<div class="section-title"><h2>${esc(title)}</h2>${label?btn(label,action,value,'text'):''}</div>`;}
// Estado vazio (Rodada 24): ilustração leve em volta do ícone, sem imagem nova (peso zero).
const EMPTY_ART='<svg viewBox="0 0 132 112" aria-hidden="true"><path class="blob" d="M66 6c22 0 44 10 52 30s4 44-12 58-42 20-64 12S8 80 10 56 26 14 46 8c7-2 13-2 20-2z"/><circle class="ring" cx="66" cy="56" r="47"/></svg>';
function empty(title,text,ic='search_off',action='',label=''){return `<div class="empty"><div class="empty-art" aria-hidden="true">${EMPTY_ART}<span class="empty-ic">${icon(ic)}</span><i class="d1"></i><i class="d2"></i><i class="d3"></i></div><h3>${esc(title)}</h3><p>${esc(text)}</p>${action?btn(label,action,'','tonal'):''}</div>`;}
function photoCard(item){
 const tag=item.status==='sold'?(item.kind==='imovel'?'Indisponível':'Vendido'):item.mine?'Seu anúncio':item.flag==='Transferido'?'Em transferência':item.kind==='imovel'?item.ptype||'Imóvel':'Desapego';
 return `<article class="photo-card">${iconBtn(item.saved?'bookmark':'bookmark_border','save-item',item.id,item.saved?'Remover dos salvos':'Salvar anúncio',`class="save-card" aria-pressed="${!!item.saved}"`)}<button type="button" class="card-link" data-action="open-item" data-value="${item.id}">${cover(item,tag)}<div class="card-body"><div class="price">${money(item.numPrice)}${item.per?'<small> / mês</small>':''}</div><h3>${esc(item.title)}</h3><p class="card-meta">${esc(item.hood)} · ${esc(item.city)}</p>${item.kind==='imovel'?propertyCardLine(item):itemCardLine(item)}</div></button></article>`;
}
function businessCard(b){return `<article class="photo-card">${iconBtn(b.saved?'bookmark':'bookmark_border','save-biz',b.id,b.saved?'Remover negócio dos salvos':'Salvar negócio',`class="save-card" aria-pressed="${!!b.saved}"`)}<button type="button" class="card-link" data-action="open-biz" data-value="${b.id}">${cover(b,b.spon?'Patrocinado':b.claimed===false?'Indicado pela comunidade':b.cat)}<div class="card-body"><h3>${esc(b.name)}</h3><p class="card-meta">${esc(b.cat)} · ${esc(b.hoods[0]||b.city)}</p><p class="card-line">${icon(b.claimed===false?'hourglass_top':'forum')}${b.claimed===false?'Aguardando o responsável':b.recN?`${b.recN} indicações da comunidade`:'Novo na cidade'}</p>${b.disc?`<p class="card-line">${icon('sell')}${esc(b.disc)}</p>`:''}</div></button></article>`;}
function questionRow(q){const n=q.answers.length;return `<button type="button" class="list-row" data-action="open-question" data-value="${q.id}"><span class="avatar ${q.mine?'me':''}">${esc(q.ini||initals(q.who))}</span><span class="txt"><b>${esc(q.q)}</b><small>${esc(q.mine?'Você':q.who)} · ${esc(q.topic||q.city)}</small><span>${pill(q.status==='ok'?'Resolvida':n?`${n} ${n===1?'resposta':'respostas'}`:'Sem resposta',q.status==='ok'?'ok':'')}</span></span>${icon('chevron_right','','false')}</button>`;}
function eventRow(e){const d=new Date(e.date+'T12:00:00');return `<div class="list-row"><button type="button" class="event-date" data-action="open-event" data-value="${e.id}" aria-label="Ver ${esc(e.title)}"><small>${d.toLocaleDateString('pt-BR',{month:'short'}).replace('.','').toUpperCase()}</small><b>${d.getDate()}</b></button><button type="button" class="txt" data-action="open-event" data-value="${e.id}"><b>${esc(e.title)}</b><small>${esc(e.place)} · ${esc(e.time)}</small><small>${e.going||0} confirmados</small></button>${btn(e.on?'Confirmado':'Vou','attend-event',e.id,e.on?'tonal':'outlined',e.on?'check':'')}</div>`;}
// notify() mora em shell/toasts.js (Rodada 33: avisos empilhados com desfazer).
